    import random
    n = problem_instance["n_cities"]
    dist = problem_instance["dist_matrix"]
    # --- Random initial tour (fix start at 0 for consistency) ---
    tour = [0] + random.sample(range(1, n), n - 1)
    # --- Helper to compute total cost ---
    def tour_cost(t):
        return sum(dist[t[i]][t[(i + 1) % n]] for i in range(n))
    best_cost = tour_cost(tour)
    # --- Limited 2-opt improvement ---
    max_iters = 200  # keep runtime low
    improved = True
    it = 0
    while improved and it < max_iters:
        improved = False
        it += 1
        for i in range(1, n - 1):
            for k in range(i + 1, n):
                # 2-opt swap between i and k (inclusive)
                new_tour = tour[:i] + tour[i:k + 1][::-1] + tour[k + 1:]
                new_cost = tour_cost(new_tour)
                if new_cost < best_cost:
                    tour, best_cost = new_tour, new_cost
                    improved = True
                    break
            if improved:
                break
    return {"tour": tour, "cost": float(best_cost)}

