import numpy as np

def heuristic(problem_instance):
    n = problem_instance["n_cities"]
    dist = problem_instance["dist_matrix"]
    if n == 0:
        return {"tour": [], "cost": 0.0}
    if n == 1:
        return {"tour": [0], "cost": 0.0}
    # Exact DP for small instances
    if n <= 15:
        INF = float('inf')
        size = 1 << n
        dp = [dict() for _ in range(size)]
        parent = [dict() for _ in range(size)]
        dp[1][0] = 0.0  # mask 1 means only city 0 visited
        for mask in range(1, size):
            if not (mask & 1):
                continue  # start city must be in mask
            for u in dp[mask]:
                cost_u = dp[mask][u]
                for v in range(1, n):
                    if mask & (1 << v):
                        continue
                    new_mask = mask | (1 << v)
                    new_cost = cost_u + dist[u][v]
                    if v not in dp[new_mask] or new_cost < dp[new_mask][v]:
                        dp[new_mask][v] = new_cost
                        parent[new_mask][v] = u
        full_mask = (1 << n) - 1
        best_cost = INF
        last_city = -1
        for u, cost_u in dp[full_mask].items():
            total = cost_u + dist[u][0]
            if total < best_cost:
                best_cost = total
                last_city = u
        # reconstruct path
        tour = [0] * n
        mask = full_mask
        city = last_city
        for i in range(n - 1, 0, -1):
            tour[i] = city
            prev = parent[mask][city]
            mask ^= (1 << city)
            city = prev
        tour[0] = 0
        return {"tour": tour, "cost": best_cost}
    # Heuristic for larger instances: Nearest Neighbor + 2-opt
    unvisited = set(range(1, n))
    tour = [0]
    while unvisited:
        cur = tour[-1]
        nxt = min(unvisited, key=lambda c: dist[cur][c])
        tour.append(nxt)
        unvisited.remove(nxt)
    # 2-opt improvement
    def tour_cost(t):
        return sum(dist[t[i]][t[(i + 1) % n]] for i in range(n))
    improved = True
    max_iter = 10
    iter_count = 0
    while improved and iter_count < max_iter:
        improved = False
        for i in range(1, n - 1):
            for k in range(i + 1, n):
                if k - i == 1:  # consecutive edges, no gain
                    continue
                a, b = tour[i - 1], tour[i]
                c, d = tour[k], tour[(k + 1) % n]
                delta = (dist[a][c] + dist[b][d]) - (dist[a][b] + dist[c][d])
                if delta < -1e-9:
                    tour[i:k + 1] = reversed(tour[i:k + 1])
                    improved = True
        iter_count += 1
    total_cost = tour_cost(tour)
    return {"tour": tour, "cost": total_cost}

